import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { AtSign, CalendarDays, ChevronLeft, ChevronRight, ClipboardList, Download, Eye, FileText, Layers3, MapPin, Pencil, Plus, RefreshCw, Search, SlidersHorizontal, Trash2, Upload, UserRound, X } from 'lucide-react';
import { SystemModal } from './SystemModal';
import { designerRequestService, formatCreatorLabel, validateReferenceFile, type CreateDesignerRequest, type DesignType, type DesignerReferenceAttachment, type DesignerRequestCreator, type DesignerRequestV2, type DesignerStage, type StageStatus, type TaskType, type WorkMode } from '../services/designer-request.service';
import { canRemoveDesignerReference, designerReferenceUploadsEnabled } from '../services/designer-reference-feature';
import { ReferenceStorageCleanupError } from '../services/designer-reference-upload';
import { useAuth } from '../hooks/useAuth';
import { usePermissions } from '../hooks/usePermissions';
import { designerPricingService, type DesignerReferencePricing, type UpdateDesignerReferencePricing } from '../services/designer-pricing.service';
import '../styles/designer-request-phase3.css';
