type Tab = 'design' | 'setup';
type DesignerMode = 'intake' | 'progress';
type DesignerWorkstream = 'creative' | 'setup';
type StageAction = 'claim' | 'arrange' | 'start' | 'submit';
type WorkflowItem = DesignerRequestV2 & { stage?: DesignerStage };
type RequestForm = CreateDesignerRequest;
type PendingReference = { file: File; scope: 'shared' | 'items'; itemIds: string[] };
type AgentStatusFilter = 'all' | 'processing' | 'awaiting' | 'completed' | 'cancelled';

type AgentFilters = { keyword: string; taskType: string; workMode: string; status: AgentStatusFilter; applicationDate: string };
type IntakeFilters = { keyword: string; taskType: string; designType: string; applicant: string; eventDate: string; submittedDate: string; region: string };
type ProgressFilters = { owner: string; stageType: string; status: string; keyword: string; applicant: string; eventDate: string; activeOnly: boolean };

const emptyForm: RequestForm = { creatorProfileId: '', workMode: 'design_only', taskType: 'daily', requestType: 'banner', otherDesignType: '', eventStartAt: '', eventEndAt: '', content: '', style: '', color: '', specification: '', specialContent: '', referenceMaterialStatus: 'not_required', liveRoom: '' };
const stageNames: Record<string, string> = { design: '设计', production: '制作', setup: '布置', unclaimed: '待接单', scheduled: '待安排', arranged: '已安排', in_progress: '进行中', awaiting_agent_confirmation: '待申请人确认', revision: '问题处理中', completed: '已完成' };
const taskTypeNames: Record<TaskType, string> = { daily: '日常', activity: '活动' };
const designTypeNames: Record<DesignType, string> = { poster: '海报', banner: 'Banner', standee: '立牌', special: '其他' };
const emptyAgentFilters: AgentFilters = { keyword: '', taskType: '', workMode: '', status: 'processing', applicationDate: '' };
const emptyIntakeFilters: IntakeFilters = { keyword: '', taskType: '', designType: '', applicant: '', eventDate: '', submittedDate: '', region: '' };
const emptyProgressFilters: ProgressFilters = { owner: '', stageType: '', status: '', keyword: '', applicant: '', eventDate: '', activeOnly: false };
const initialProgressFilters: ProgressFilters = { ...emptyProgressFilters, activeOnly: true };

function displayStageStatus(stage: DesignerStage): string {
  if (stage.stage_type === 'design' && stage.status === 'in_progress') return '设计中';
  if (stage.stage_type === 'production' && stage.status === 'in_progress') return '制作中';
  if (stage.stage_type === 'setup' && stage.status === 'in_progress') return '布置中';
  if (stage.stage_type === 'production' && stage.status === 'awaiting_agent_confirmation') return '待申请人最终确认';
  return stageNames[stage.status] ?? stage.status;
}

export function AgentDesignerRequests() {
  const permissions = usePermissions();
  const [items, setItems] = useState<DesignerRequestV2[]>([]);
  const [creators, setCreators] = useState<DesignerRequestCreator[]>([]);
  const [tab, setTab] = useState<Tab>('design');
  const [form, setForm] = useState<RequestForm | null>(null); const [editing, setEditing] = useState<DesignerRequestV2 | null>(null); const [cancelling, setCancelling] = useState<DesignerRequestV2 | null>(null);
  const [detail, setDetail] = useState<DesignerRequestV2 | null>(null);
  const [requestsError, setRequestsError] = useState('');
  const [creatorsError, setCreatorsError] = useState('');
  const [actionError, setActionError] = useState('');
  const [requestsLoading, setRequestsLoading] = useState(true);
  const [creatorsLoading, setCreatorsLoading] = useState(true);
  const [filters, setFilters] = useState<AgentFilters>(emptyAgentFilters);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [pricing, setPricing] = useState<DesignerReferencePricing | null>(null);
  const [pricingLoading, setPricingLoading] = useState(true);
  const [pricingError, setPricingError] = useState('');
  const [pricingEditorOpen, setPricingEditorOpen] = useState(false);
  const [submittingRequest, setSubmittingRequest] = useState(false);
  const [createdRequestId, setCreatedRequestId] = useState<string | null>(null);
  const submissionLocked = useRef(false);
  const uploadedReferences = useRef(new Set<PendingReference>());
  const load = useCallback(async () => {
    setRequestsLoading(true); setCreatorsLoading(true); setPricingLoading(true); setRequestsError(''); setCreatorsError(''); setPricingError('');
    await Promise.all([
      designerRequestService.listAgentRequests().then(setItems).catch((reason: unknown) => setRequestsError(errorMessage(reason))).finally(() => setRequestsLoading(false)),
      designerRequestService.listEligibleCreators().then(setCreators).catch((reason: unknown) => setCreatorsError(errorMessage(reason))).finally(() => setCreatorsLoading(false)),
      designerPricingService.getReferencePricing().then(setPricing).catch((reason: unknown) => { setPricing(null); setPricingError(`参考价格读取失败：${errorMessage(reason)}`); }).finally(() => setPricingLoading(false)),
    ]);
  }, []);
  useEffect(() => { void load(); }, [load]);
  const canEditPricing = permissions.isSuperAdmin || permissions.hasPermission('designer-pricing:manage', 'use');
  const agentBase = useMemo(() => items
    .filter((request) => (tab === 'setup' ? request.work_mode === 'setup_only' : request.work_mode !== 'setup_only'))
    .filter((request) => matchesKeyword(request, filters.keyword))
    .filter((request) => !filters.taskType || request.task_type === filters.taskType)
    .filter((request) => !filters.workMode || request.work_mode === filters.workMode)
    .filter((request) => !filters.applicationDate || malaysiaDateKey(request.created_at) === filters.applicationDate), [items, tab, filters.keyword, filters.taskType, filters.workMode, filters.applicationDate]);
  const counts = useMemo(() => agentBase.reduce((result, item) => ({ ...result, [agentBucket(item)]: result[agentBucket(item)] + 1 }), { all: agentBase.length, processing: 0, awaiting: 0, completed: 0, cancelled: 0 }), [agentBase]);
  const visible = useMemo(() => agentBase.filter((request) => filters.status === 'all' || agentBucket(request) === filters.status).sort(sortAgentRequests), [agentBase, filters.status]);
  async function submit(event: FormEvent<HTMLFormElement>, files: PendingReference[], note: string) { event.preventDefault(); if (!form || submissionLocked.current) return; if(files.some((file)=>file.scope==='items'&&!file.itemIds.length)){setActionError('指定项目参考资料至少需要选择一个项目。');return;} submissionLocked.current=true; setSubmittingRequest(true); setActionError(''); let requestId=editing?.id ?? createdRequestId; try { if(!requestId){requestId=await designerRequestService.create(form);setCreatedRequestId(requestId);} if(editing) await designerRequestService.update(requestId, form); if(designerReferenceUploadsEnabled){await designerRequestService.updateReferenceNote(requestId,note);for(const reference of files){if(uploadedReferences.current.has(reference))continue;await designerRequestService.uploadReference(requestId,reference.file,reference.scope,reference.itemIds);uploadedReferences.current.add(reference);}} setForm(null); setEditing(null); setCreatedRequestId(null); uploadedReferences.current.clear(); await load(); } catch (reason) { setActionError(!editing&&requestId?`申请已创建；资料提交失败。请重试资料提交，不会重复创建申请。${errorMessage(reason)}`:errorMessage(reason)); } finally { submissionLocked.current=false; setSubmittingRequest(false); } }
  function edit(request: DesignerRequestV2) { setCreatedRequestId(null); uploadedReferences.current.clear(); setEditing(request); setForm({ creatorProfileId: request.creator_profile_id ?? '', workMode: request.work_mode ?? 'design_only', taskType: request.task_type ?? 'daily', requestType: request.request_type, otherDesignType: request.other_design_type ?? '', eventStartAt: dateInput(request.event_start_at), eventEndAt: dateInput(request.event_end_at), content: request.design_content ?? '', specialContent: request.special_content ?? '', style: request.style ?? '', color: request.color ?? '', specification: request.specification ?? '', referenceMaterialStatus: request.reference_material_status, liveRoom: request.live_room ?? '' }); }
  async function cancel() { if (!cancelling) return; setActionError(''); try { await designerRequestService.cancel(cancelling.id); setCancelling(null); setDetail(null); await load(); } catch (reason) { setActionError(errorMessage(reason)); } }
  async function review(stage: DesignerStage, accepted: boolean) { setActionError(''); try { if (accepted) await designerRequestService.confirm(stage.id); else { const note = window.prompt('请填写问题说明'); if (!note?.trim()) return; await designerRequestService.returnStage(stage.id, note); } setDetail(null); await load(); } catch (reason) { setActionError(errorMessage(reason)); } }
  return <section className="designer-request-page">
    <header className="designer-request-hero designer-request-agent-hero">
      <div className="designer-request-agent-heading"><span>DESIGNER REQUEST</span><h2>美工申请</h2><p>提交设计、制作及活动布置需求，并在此跟进申请进度。</p></div>
      <button className="designer-request-primary" type="button" onClick={() => { setCreatedRequestId(null); uploadedReferences.current.clear(); setForm({ ...emptyForm, workMode: tab === 'setup' ? 'setup_only' : 'design_only' }); }}><Plus size={17} />新增申请</button>
    </header>
    <section className="designer-request-pricing" aria-labelledby="designer-request-pricing-title">
      <div className="designer-request-pricing-heading"><div><span>服务价格与申请规则</span><h3 id="designer-request-pricing-title">制作服务</h3></div>{canEditPricing ? <button className="designer-request-pricing-edit" type="button" onClick={() => setPricingEditorOpen(true)} disabled={!pricing || pricingLoading}>编辑价格</button> : null}</div>
      <div className="designer-request-guides" aria-label="美工申请说明与价格规则">
        <section className="designer-request-guide"><div className="designer-request-guide-heading"><strong>Banner 制作</strong><b>{pricingLabel(pricing?.banner_production_price, pricingLoading, pricingError)} <small>/ 次</small></b></div><div className="designer-request-guide-details"><span>默认尺寸：100cm × 30cm</span></div><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-time"><span>时间</span><small>制作周期：10–15天，请提前安排</small></div><div className="designer-request-guide-rule designer-request-guide-online"><span>线上主播</span><small>月流水每达 <em>200K</em>，可申请 <em>1次 Banner 制作</em></small></div><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
        <section className="designer-request-guide"><div className="designer-request-guide-heading"><strong>立牌制作</strong><b>{pricingLabel(pricing?.standee_production_price, pricingLoading, pricingError)} <small>/ 次</small></b></div><div className="designer-request-guide-details"><span>制作周期：10–15天，请提前安排</span></div><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
        <section className="designer-request-guide"><div className="designer-request-guide-heading"><strong>活动设计与布置</strong><b>{pricingLabel(pricing?.event_design_setup_price, pricingLoading, pricingError)} <small>/ 次</small></b></div><div className="designer-request-guide-details"><span>含基础直播间背景布置及道具搭配</span><span>额外需求将另行评估与报价</span></div><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-time"><span>时间</span><small>所有活动海报及布置需求须至少提前10天申请</small></div><div className="designer-request-guide-rule designer-request-guide-rule-detail"><small>逾期申请无法保证按时完成</small></div><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
      </div>
      {pricingError ? <p className="designer-pricing-read-error">{pricingError}</p> : null}
    </section>
    <div className="designer-request-workbench">
      <div className="designer-request-workbench-header designer-request-agent-workbench-header">
        <div className="designer-request-tabs" role="tablist"><button type="button" className={tab === 'design' ? 'is-active' : ''} onClick={() => setTab('design')}>设计 / 制作</button><button type="button" className={tab === 'setup' ? 'is-active' : ''} onClick={() => setTab('setup')}>布置</button></div>
        <button className="designer-request-secondary designer-request-refresh" type="button" onClick={() => void load()}><RefreshCw size={16} />刷新</button>
      </div>
      <div className="designer-request-summary" aria-label="申请统计">{([['all', '全部'], ['processing', '处理中'], ['awaiting', '待我确认'], ['completed', '已完成'], ['cancelled', '已取消']] as const).map(([value, label]) => <button key={value} type="button" className={`designer-request-summary-card${value === 'awaiting' ? ' is-attention' : ''}${filters.status === value ? ' is-selected' : ''}`} onClick={() => setFilters((current) => ({ ...current, status: value }))}><span>{label}</span><strong>{counts[value]}</strong></button>)}</div>
      <button type="button" className="designer-request-filter-toggle" onClick={() => setFiltersOpen((open) => !open)}><SlidersHorizontal size={16} />筛选</button>
      <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={filters.keyword} onChange={(event) => setFilters({ ...filters, keyword: event.target.value })} /></label><SelectFilter label="任务类型" value={filters.taskType} onChange={(taskType) => setFilters({ ...filters, taskType })} options={[['daily', '日常'], ['activity', '活动']]} /><SelectFilter label="工作方式" value={filters.workMode} onChange={(workMode) => setFilters({ ...filters, workMode })} options={[['design_only', '纯设计'], ['design_production', '设计 + 制作'], ['setup_only', '活动布置']]} /><SelectFilter label="状态" value={filters.status} onChange={(status) => setFilters({ ...filters, status: status as AgentStatusFilter })} options={[['all', '全部'], ['processing', '处理中'], ['awaiting', '待我确认'], ['completed', '已完成'], ['cancelled', '已取消']]} /><label className="designer-request-filter-field"><span>申请日期</span><input type="date" value={filters.applicationDate} onChange={(event) => setFilters({ ...filters, applicationDate: event.target.value })} /></label><button className="designer-request-reset" type="button" onClick={() => setFilters(emptyAgentFilters)}>重置</button></RequestFilters>
      {requestsError ? <p className="designer-request-read-error">申请列表读取失败：{requestsError}</p> : null}{actionError ? <p className="designer-request-read-error">操作失败：{actionError}</p> : null}{requestsLoading ? <div className="designer-request-empty">正在读取申请…</div> : <RequestTable items={visible} onDetail={setDetail} onEdit={edit} onCancel={setCancelling} agent hideDesignType={tab === 'setup'} />}
    </div>
    {pricingEditorOpen && pricing ? <DesignerPricingModal pricing={pricing} onClose={() => setPricingEditorOpen(false)} onSaved={async (next) => { setPricing(next); setPricingEditorOpen(false); }} /> : null}{form ? <RequestFormModal form={form} creators={creators} creatorsLoading={creatorsLoading} creatorsError={creatorsError} editing={editing} submitting={submittingRequest} retryingAttachments={Boolean(createdRequestId)} onChange={setForm} onClose={() => { if(submittingRequest)return; setForm(null); setEditing(null); setCreatedRequestId(null); uploadedReferences.current.clear(); }} onSubmit={submit} /> : null}{detail ? <RequestDetail request={detail} applicant onClose={() => setDetail(null)} onReview={review} /> : null}{cancelling ? <CancelModal onClose={() => setCancelling(null)} onConfirm={cancel} /> : null}
  </section>;
}

function pricingLabel(value: number | undefined, loading: boolean, error: string) {
  if (loading) return '价格读取中…';
  if (error || value === undefined) return '价格不可用';
  return `RM${value.toFixed(2)}`;
}

function DesignerPricingModal({ pricing, onClose, onSaved }: { pricing: DesignerReferencePricing; onClose: () => void; onSaved: (pricing: DesignerReferencePricing) => Promise<void> }) {
  const [draft, setDraft] = useState<UpdateDesignerReferencePricing>({ banner_production_price: pricing.banner_production_price, standee_production_price: pricing.standee_production_price, event_design_setup_price: pricing.event_design_setup_price });
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const fields: Array<[keyof UpdateDesignerReferencePricing, string]> = [['banner_production_price', 'Banner 制作'], ['standee_production_price', '立牌制作'], ['event_design_setup_price', '活动设计与布置']];

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saving) return;
    const values = Object.values(draft);
    if (values.some((value) => !Number.isFinite(value) || value < 0 || Math.round(value * 100) !== value * 100)) {
      setError('请输入非负金额，且最多保留两位小数。');
      return;
    }
    setSaving(true); setError('');
    try {
      await onSaved(await designerPricingService.updateReferencePricing(draft));
    } catch (reason) {
      setError(`保存参考价格失败：${errorMessage(reason)}`);
    } finally {
      setSaving(false);
    }
  }

  return <SystemModal title="编辑美工参考收费" subtitle="仅更新页面参考价格，不影响现有申请、审批或计算" className="designer-pricing-modal" wide={false} onClose={saving ? () => undefined : onClose} footer={<><button className="designer-request-secondary" type="button" onClick={onClose} disabled={saving}>取消</button><button className="designer-request-primary" form="designer-pricing-form" type="submit" disabled={saving}>{saving ? '保存中…' : '保存全部价格'}</button></>}><form id="designer-pricing-form" className="designer-request-form" onSubmit={submit}><fieldset className="designer-request-section"><legend>参考价格</legend><div className="designer-pricing-grid">{fields.map(([key, label]) => <label className="designer-request-field" key={key}><span>{label}</span><input type="number" min="0" step="0.01" inputMode="decimal" value={Number.isFinite(draft[key]) ? draft[key] : ''} onChange={(event) => setDraft({ ...draft, [key]: event.target.value === '' ? Number.NaN : Number(event.target.value) })} disabled={saving} required /><small>RM · 最多两位小数</small></label>)}</div></fieldset>{error ? <p className="form-alert">{error}</p> : null}</form></SystemModal>;
}

export function DesignerWorkflow({ mode }: { mode: DesignerMode }) {
  const { profile } = useAuth(); const [items, setItems] = useState<WorkflowItem[]>([]); const [detail, setDetail] = useState<WorkflowItem | null>(null); const [error, setError] = useState(''); const [workstream, setWorkstream] = useState<DesignerWorkstream>('creative'); const [filtersOpen, setFiltersOpen] = useState(false); const [intakeFilters, setIntakeFilters] = useState<IntakeFilters>(emptyIntakeFilters); const [progressFilters, setProgressFilters] = useState<ProgressFilters>(initialProgressFilters);
  const load = useCallback(async () => { try { const next = mode === 'intake' ? await designerRequestService.listAvailableStages() : profile?.id ? await designerRequestService.listMyStages(profile.id) : []; setItems(next); } catch (reason) { setError(errorMessage(reason)); } }, [mode, profile?.id]);
  useEffect(() => { void load(); }, [load]);
  async function act(stage: DesignerStage, action: StageAction) { try { if (action === 'claim') await designerRequestService.claim(stage.id); else if (action === 'arrange' || action === 'start') await designerRequestService.advance(stage.id, action); else await designerRequestService.submit(stage.id); setDetail(null); await load(); } catch (reason) { setError(errorMessage(reason)); } }
  const regions = useMemo(() => Array.from(new Set(items.map((item) => item.region?.name).filter((value): value is string => Boolean(value)))).sort(), [items]);
  const applicants = useMemo(() => Array.from(new Set(items.map((item) => displayEmployee(item.applicant, '')).filter(Boolean))).sort(), [items]);
  const visible = useMemo(() => items.filter((item) => workstream === 'setup' ? item.stage?.stage_type === 'setup' && item.work_mode === 'setup_only' : (item.stage?.stage_type === 'design' || item.stage?.stage_type === 'production') && item.work_mode !== 'setup_only').filter((item) => mode === 'intake' ? matchesIntake(item, intakeFilters, workstream) : matchesProgress(item, progressFilters)).sort(mode === 'intake' ? (first, second) => sortIntakeRequests(first, second, workstream) : sortProgressRequests), [items, workstream, mode, intakeFilters, progressFilters]);
  return <section className="designer-request-page"><header className="designer-request-hero"><div><span>DY GROUP · CREATIVE DESK</span><h2>{mode === 'intake' ? '接单中心' : '我的工作进度'}</h2><p>{mode === 'intake' ? '选择设计 / 制作或活动布置工作区接单。' : '按工作区继续完成已接任务。'}</p></div></header><div className="designer-request-workbench"><div className="designer-request-workbench-header"><div className="designer-request-tabs" role="tablist"><button className={workstream === 'creative' ? 'is-active' : ''} type="button" onClick={() => setWorkstream('creative')}>设计 / 制作</button><button className={workstream === 'setup' ? 'is-active' : ''} type="button" onClick={() => setWorkstream('setup')}>活动布置</button></div><button className="designer-request-secondary designer-request-refresh" type="button" onClick={() => void load()}><RefreshCw size={16} />刷新</button></div>{workstream === 'setup' ? <p className="designer-request-setup-note"><strong>布置费用：RM50/次</strong>，包含基础直播间背景布置和道具搭配；额外需求另评估报价。至少提前 10 天申请，少于 10 天无法保证按时完成。</p> : null}{mode === 'progress' ? <button type="button" className={`designer-request-quick-filter${progressFilters.activeOnly ? ' is-selected' : ''}`} onClick={() => setProgressFilters({ ...emptyProgressFilters, activeOnly: true })}>我的进行中任务</button> : null}<button type="button" className="designer-request-filter-toggle" onClick={() => setFiltersOpen((open) => !open)}><SlidersHorizontal size={16} />筛选</button>{mode === 'intake' ? <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={intakeFilters.keyword} onChange={(event) => setIntakeFilters({ ...intakeFilters, keyword: event.target.value })} /></label><SelectFilter label="任务类型" value={intakeFilters.taskType} onChange={(taskType) => setIntakeFilters({ ...intakeFilters, taskType })} options={[['daily', '日常'], ['activity', '活动']]} />{workstream === 'creative' ? <SelectFilter label="设计类型" value={intakeFilters.designType} onChange={(designType) => setIntakeFilters({ ...intakeFilters, designType })} options={Object.entries(designTypeNames)} /> : null}<SelectFilter label="申请人" value={intakeFilters.applicant} onChange={(applicant) => setIntakeFilters({ ...intakeFilters, applicant })} options={applicants.map((value) => [value, value])} /><DateFilter label="活动日期" value={intakeFilters.eventDate} onChange={(eventDate) => setIntakeFilters({ ...intakeFilters, eventDate })} /><DateFilter label="提交日期" value={intakeFilters.submittedDate} onChange={(submittedDate) => setIntakeFilters({ ...intakeFilters, submittedDate })} /><SelectFilter label="区域" value={intakeFilters.region} onChange={(region) => setIntakeFilters({ ...intakeFilters, region })} options={regions.map((value) => [value, value])} /><button className="designer-request-reset" type="button" onClick={() => setIntakeFilters(emptyIntakeFilters)}>重置</button></RequestFilters> : <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-filter-field"><span>负责人</span><input placeholder="搜索负责人" value={progressFilters.owner} onChange={(event) => setProgressFilters({ ...progressFilters, owner: event.target.value, activeOnly: false })} /></label><SelectFilter label="当前阶段" value={progressFilters.stageType} onChange={(stageType) => setProgressFilters({ ...progressFilters, stageType, activeOnly: false })} options={[['design', '设计'], ['production', '制作'], ['setup', '布置']]} /><SelectFilter label="状态" value={progressFilters.status} onChange={(status) => setProgressFilters({ ...progressFilters, status, activeOnly: false })} options={[['scheduled', '待安排'], ['arranged', '已安排'], ['in_progress', '进行中'], ['awaiting_agent_confirmation', '待申请人确认'], ['revision', '问题处理中']]} /><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={progressFilters.keyword} onChange={(event) => setProgressFilters({ ...progressFilters, keyword: event.target.value, activeOnly: false })} /></label><SelectFilter label="申请人" value={progressFilters.applicant} onChange={(applicant) => setProgressFilters({ ...progressFilters, applicant, activeOnly: false })} options={applicants.map((value) => [value, value])} /><DateFilter label="活动日期" value={progressFilters.eventDate} onChange={(eventDate) => setProgressFilters({ ...progressFilters, eventDate, activeOnly: false })} /><button className="designer-request-reset" type="button" onClick={() => setProgressFilters(emptyProgressFilters)}>重置</button></RequestFilters>}{error ? <p className="form-alert">{error}</p> : null}<RequestTable items={visible} onDetail={setDetail} intake={mode === 'intake'} progress={mode === 'progress'} hideDesignType={workstream === 'setup'} /></div>{detail ? <RequestDetail request={detail} stage={detail.stage} intake={mode === 'intake'} onClose={() => setDetail(null)} onStageAction={act} /> : null}</section>;
}

export function RequestTable({ items, onDetail, onEdit, onCancel, agent = false, intake = false, progress = false, hideDesignType = false }: { items: WorkflowItem[]; onDetail: (request: WorkflowItem) => void; onEdit?: (request: DesignerRequestV2) => void; onCancel?: (request: DesignerRequestV2) => void; agent?: boolean; intake?: boolean; progress?: boolean; hideDesignType?: boolean }) {
  const [preview, setPreview] = useState<DesignerRequestV2 | null>(null);
  if (agent) return <div className="designer-request-list designer-request-main-list">{items.length === 0 ? <div className="designer-request-empty">暂无符合条件的美工申请。</div> : <><div className="designer-request-table-wrap"><table className="designer-request-table designer-request-main-table"><thead><tr><th>主播</th><th>申请人 / 经纪人</th><th>申请项目</th><th>当前进度</th><th>最新设计成果</th><th>美工</th><th>活动日期</th><th>操作</th></tr></thead><tbody>{items.map((request) => <MainRequestRow key={request.id} request={request} onDetail={onDetail} onEdit={onEdit} onCancel={onCancel} onPreview={setPreview} />)}</tbody></table></div><div className="designer-request-cards designer-request-main-cards">{items.map((request) => <MainRequestCard key={request.id} request={request} onDetail={onDetail} onEdit={onEdit} onCancel={onCancel} onPreview={setPreview} />)}</div></>}{preview ? <DesignResultPreview request={preview} onClose={() => setPreview(null)} /> : null}</div>;
  return <div className="designer-request-list">{items.length === 0 ? <div className="designer-request-empty">暂无符合条件的美工申请。</div> : <><div className="designer-request-table-wrap"><table className={`designer-request-table${hideDesignType ? ' designer-request-table-setup' : ''}`}><thead><tr>{progress ? <th>当前阶段</th> : null}<th>任务类型</th><th>工作方式</th>{!hideDesignType ? <th>设计类型</th> : null}<th>主播</th><th>申请人</th><th>状态</th><th>操作</th></tr></thead><tbody>{items.map((request) => { const stage = request.stage; return <tr key={`${request.id}-${stage?.id ?? 'request'}`}>{progress ? <td>{stageNames[stage?.stage_type ?? '']}</td> : null}<td>{displayTaskType(request.task_type)}</td><td>{workModeLabel(request.work_mode)}</td>{!hideDesignType ? <td>{displayDesignType(request)}</td> : null}<td>{request.creator_name || '-'}</td><td>{displayEmployee(request.applicant, '-')}</td><td><StatusBadge value={stage ? displayStageStatus(stage) : request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ')} /></td><td><div className="designer-request-row-actions"><button className="designer-request-icon" type="button" onClick={() => onDetail(request)} aria-label="查看"><Eye size={16} /></button>{intake ? <button className="designer-request-text-action" type="button" onClick={() => onDetail(request)}>接单</button> : null}{progress && stage ? <span className="designer-request-next">{actionLabel(nextAction(stage.status, false))}</span> : null}</div></td></tr>; })}</tbody></table></div><div className="designer-request-cards">{items.map((request) => <article className="designer-request-card" key={`${request.id}-${request.stage?.id ?? 'card'}`}><div><small>{progress ? `当前阶段：${stageNames[request.stage?.stage_type ?? '']}` : displayTaskType(request.task_type)}</small><h3>{request.creator_name || '-'}</h3><p>{workModeLabel(request.work_mode)}{request.work_mode !== 'setup_only' ? ` · ${displayDesignType(request)}` : ''}</p></div><StatusBadge value={request.stage ? displayStageStatus(request.stage) : request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ')} /><p>申请人：{displayEmployee(request.applicant, '-')}</p><button className="designer-request-text-action" type="button" onClick={() => onDetail(request)}>查看</button></article>)}</div></>}</div>;
}

function MainRequestRow({ request, onDetail, onEdit, onCancel, onPreview }: { request: DesignerRequestV2; onDetail: (request: WorkflowItem) => void; onEdit?: (request: DesignerRequestV2) => void; onCancel?: (request: DesignerRequestV2) => void; onPreview: (request: DesignerRequestV2) => void }) { const eligible = canEditRequest(request); return <tr><td><CreatorCell request={request} /></td><td><ApplicantAgentCell request={request} /></td><td><RequestItems request={request} /></td><td><RequestProgress request={request} /></td><td><ResultThumb request={request} onPreview={onPreview} /></td><td><DesignerCell request={request} /></td><td><EventCell request={request} /></td><td><RowActions request={request} eligible={eligible} onDetail={onDetail} onEdit={onEdit} onCancel={onCancel} /></td></tr>; }
function MainRequestCard(props: Parameters<typeof MainRequestRow>[0]) { const { request, onDetail, onEdit, onCancel, onPreview } = props; return <article className="designer-request-card designer-request-main-card"><CreatorCell request={request} /><ApplicantAgentCell request={request} /><RequestItems request={request} /><RequestProgress request={request} /><div className="designer-main-card-grid"><span><small>美工</small><DesignerCell request={request} /></span><span><small>活动</small><EventCell request={request} /></span></div><ResultThumb request={request} onPreview={onPreview} /><RowActions request={request} eligible={canEditRequest(request)} onDetail={onDetail} onEdit={onEdit} onCancel={onCancel} /></article>; }
function canEditRequest(request: DesignerRequestV2) { return request.status === 'unclaimed' && request.stages.every((item) => !item.assignee_profile_id && !item.accepted_at && (item.status === 'unclaimed' || item.status === 'scheduled')); }
function CreatorCell({ request }: { request: DesignerRequestV2 }) { const name = request.creator_name || '-'; return <div className="designer-main-creator"><div><b>{name}</b><small>{request.platform_account || request.platform_user_id || '平台账号未提供'}</small><em>#{request.id.slice(0, 8).toUpperCase()}</em></div></div>; }
function ApplicantAgentCell({ request }: { request: DesignerRequestV2 }) { return <div className="designer-personnel-pair"><span><small>申请：</small><b>{displayEmployee(request.applicant, '未指定')}</b></span><span><small>经纪：</small><b>{displayEmployee(request.creator?.manager ?? null, '未指定')}</b></span></div>; }
function RequestItems({ request }: { request: DesignerRequestV2 }) { const items = request.request_items.length ? request.request_items : [{ id: 'legacy', item_type: request.work_mode === 'setup_only' ? 'setup' : request.request_type, item_name: null }]; return <div className="designer-main-items"><div>{items.slice(0, 2).map((item) => <span key={item.id} className={`designer-item-badge is-${item.item_type}`}>{item.item_name || itemLabel(item.item_type, request)}</span>)}</div><small>{items.length} 个项目 · {displayTaskType(request.task_type)}</small></div>; }
function RequestProgress({ request }: { request: DesignerRequestV2 }) { const stages = request.stages; const active = stages.find((stage) => stage.status !== 'completed' && stage.status !== 'cancelled'); const label = request.status === 'cancelled' ? '已取消' : active ? displayStageStatus(active) : stages.length ? '已完成' : '待处理'; return <div className="designer-main-progress"><StatusBadge value={label} /><div className="designer-stage-nodes">{stages.length ? stages.map((stage) => <span key={stage.id} className={`is-${stage.status}${active?.id === stage.id ? ' is-current' : ''}`} title={`${stageNames[stage.stage_type]}：${displayStageStatus(stage)}`}><i />{stageNames[stage.stage_type]}</span>) : <small>暂无阶段记录</small>}</div></div>; }
function ResultThumb({ request, onPreview }: { request: DesignerRequestV2; onPreview: (request: DesignerRequestV2) => void }) { const results = request.design_urls; return results.length ? <button className="designer-result-thumb designer-result-thumb-stack" type="button" onClick={() => onPreview(request)} aria-label="预览设计成果">{results.slice(0, 3).map((url, index) => <img src={url} alt="" key={url} style={{ zIndex: 3 - index }} />)}<span>{results.length} 项</span></button> : <span className="designer-result-empty">暂无成果</span>; }
function EmployeeCell({ employee, fallback }: { employee: { full_name: string | null; nickname: string | null; avatar_url?: string | null } | null; fallback: string }) { const name = displayEmployee(employee, fallback); return <div className="designer-main-owner">{employee?.avatar_url ? <img src={employee.avatar_url} alt="" /> : <i>{name.slice(0, 1).toUpperCase()}</i>}<b>{name}</b></div>; }
function DesignerCell({ request }: { request: DesignerRequestV2 }) { const designers = request.stages.reduce<Array<{ employeeId: string; employee: NonNullable<DesignerStage['assignee']> }>>((result, stage) => { if (!stage.assignee) return result; const employeeId = stage.assignee_employee_id ?? `stage:${stage.id}`; return result.some((designer) => designer.employeeId === employeeId) ? result : [...result, { employeeId, employee: stage.assignee }]; }, []); if (!designers.length) return <span className="designer-unclaimed">待接单</span>; if (designers.length === 1) return <EmployeeCell employee={designers[0].employee} fallback="待接单" />; return <details className="designer-multiple-designers"><summary>多人负责 <em>{designers.length}</em></summary><div>{designers.map(({ employeeId, employee }) => <EmployeeCell key={employeeId} employee={employee} fallback="-" />)}</div></details>; }
function EventCell({ request }: { request: DesignerRequestV2 }) { return <div className="designer-main-event"><b>{formatDate(request.event_start_at)}</b>{request.live_room ? <small>{request.live_room}</small> : null}</div>; }
function RowActions({ request, eligible, onDetail, onEdit, onCancel }: { request: DesignerRequestV2; eligible: boolean; onDetail: (request: WorkflowItem) => void; onEdit?: (request: DesignerRequestV2) => void; onCancel?: (request: DesignerRequestV2) => void }) { return <div className="designer-request-row-actions"><button className="designer-request-text-action" type="button" onClick={() => onDetail(request)}><Eye size={14} />查看详情</button>{eligible ? <><button className="designer-request-icon" type="button" aria-label="修改" onClick={() => onEdit?.(request)}><Pencil size={15} /></button><button className="designer-request-icon is-danger" type="button" aria-label="取消" onClick={() => onCancel?.(request)}><X size={15} /></button></> : null}</div>; }
function DesignResultPreview({ request, onClose }: { request: DesignerRequestV2; onClose: () => void }) { const [index, setIndex] = useState(Math.max(request.design_urls.length - 1, 0)); const [size, setSize] = useState<{ width: number; height: number } | null>(null); const url = request.design_urls[index]; const filenameParts = url ? url.split('?')[0].split('/') : []; const filename = url ? decodeURIComponent(filenameParts[filenameParts.length - 1] || `成果 ${index + 1}`) : ''; const move = (step: number) => { setSize(null); setIndex((current) => (current + step + request.design_urls.length) % request.design_urls.length); }; if (!url) return null; return <div className="designer-result-preview" role="dialog" aria-modal="true" aria-label="设计成果预览" onMouseDown={onClose}><section onMouseDown={(event) => event.stopPropagation()}><button className="designer-result-close" type="button" onClick={onClose} aria-label="关闭"><X size={20} /></button><div className="designer-result-stage"><button type="button" onClick={() => move(-1)} disabled={request.design_urls.length < 2} aria-label="上一张"><ChevronLeft size={24} /></button><img src={url} alt={filename} onLoad={(event) => setSize({ width: event.currentTarget.naturalWidth, height: event.currentTarget.naturalHeight })} /><button type="button" onClick={() => move(1)} disabled={request.design_urls.length < 2} aria-label="下一张"><ChevronRight size={24} /></button></div><aside><small>设计成果 {index + 1} / {request.design_urls.length}</small><h4 title={filename}>{filename}</h4><p>{size ? `${size.width} × ${size.height} px` : '正在读取尺寸…'}<br />文件大小：现有资料未提供</p><div className="designer-result-versions">{request.design_urls.map((item, itemIndex) => <button type="button" className={itemIndex === index ? 'is-active' : ''} key={item} onClick={() => { setSize(null); setIndex(itemIndex); }}><img src={item} alt={`版本 ${itemIndex + 1}`} /></button>)}</div><a className="designer-request-text-action" href={url} download={filename}><Download size={14} />下载原图</a></aside></section></div>; }

function RequestFilters({ className, children }: { className: string; children: ReactNode }) { return <div className={`designer-request-filters ${className}`}>{children}</div>; }
function SelectFilter({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: readonly (readonly [string, string])[] }) { return <label className="designer-request-filter-field"><span>{label}</span><select value={value} onChange={(event) => onChange(event.target.value)}><option value="">全部</option>{options.map(([optionValue, optionLabel]) => <option key={optionValue} value={optionValue}>{optionLabel}</option>)}</select></label>; }
function DateFilter({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="designer-request-filter-field"><span>{label}</span><input type="date" value={value} onChange={(event) => onChange(event.target.value)} /></label>; }
function RiskBadge({ label }: { label: string }) { return <span className={`designer-request-risk${label === '已过活动日期' ? ' is-overdue' : ''}`}>{label}</span>; }

function RequestFormModal({ form, creators, creatorsLoading, creatorsError, editing, submitting, retryingAttachments, onChange, onClose, onSubmit }: { form: RequestForm; creators: DesignerRequestCreator[]; creatorsLoading: boolean; creatorsError: string; editing: DesignerRequestV2 | null; submitting: boolean; retryingAttachments: boolean; onChange: (form: RequestForm) => void; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>, files: PendingReference[], note: string) => void }) { const creator = creators.find((item) => item.id === form.creatorProfileId); const setup = form.workMode === 'setup_only'; const [files,setFiles]=useState<PendingReference[]>([]); const [note,setNote]=useState(editing?.reference_note ?? ''); const addFiles=(incoming:FileList|File[])=>{const next:PendingReference[]=[];for(const file of Array.from(incoming)){try{validateReferenceFile(file);if(!files.some((current)=>current.file.name===file.name&&current.file.size===file.size))next.push({file,scope:'shared',itemIds:[]});}catch(reason){window.alert(errorMessage(reason));}}setFiles((current)=>[...current,...next]);}; const submitLabel=submitting?'提交中…':editing?'保存修改':retryingAttachments?'重试资料提交':'提交申请'; return <SystemModal title={editing ? '修改申请' : setup ? '新增布置申请' : '新增设计 / 制作申请'} className="designer-request-modal" onClose={onClose} footer={<><button className="designer-request-secondary" type="button" onClick={onClose} disabled={submitting}>返回</button><button className="designer-request-primary" type="submit" form="designer-request-form" disabled={submitting}>{submitLabel}</button></>}><form id="designer-request-form" className="designer-request-form" onSubmit={(event)=>onSubmit(event,files,note)}><fieldset disabled={submitting} className="designer-request-section"><legend>主播资料</legend>{creatorsError ? <p className="designer-request-read-error">主播列表读取失败：{creatorsError}</p> : null}<div className="designer-request-form-grid"><Field label="主播"><select required disabled={Boolean(editing) || creatorsLoading || Boolean(creatorsError)} value={form.creatorProfileId} onChange={(event) => onChange({ ...form, creatorProfileId: event.target.value })}><option value="">{creatorsLoading ? '正在读取授权主播…' : creatorsError ? '主播列表读取失败' : '请选择授权区域内主播'}</option>{creators.map((item) => <option value={item.id} key={item.id}>{formatCreatorLabel(item)}</option>)}</select></Field><Field label="TikTok 名字 / ID"><input readOnly value={creator ? `${creator.creator_name} / ${creator.platform_user_id}` : editing ? `${editing.creator_name || '-'} / ${editing.platform_user_id || '-'}` : '选择主播后自动带入'} /></Field></div></fieldset><fieldset disabled={submitting} className="designer-request-section"><legend>任务资料</legend><div className="designer-request-form-grid"><Field label="工作方式"><select disabled={Boolean(editing)} value={form.workMode} onChange={(event) => onChange({ ...form, workMode: event.target.value as WorkMode })}><option value="design_only">纯设计</option><option value="design_production">设计 + 制作</option><option value="setup_only">布置</option></select></Field><Field label="任务类型"><select required value={form.taskType} onChange={(event) => onChange({ ...form, taskType: event.target.value as TaskType })}><option value="daily">日常</option><option value="activity">活动</option></select></Field>{!setup ? <Field label="设计类型"><select required value={form.requestType} onChange={(event) => { const requestType = event.target.value as DesignType; onChange({ ...form, requestType, otherDesignType: requestType === 'special' ? form.otherDesignType : '' }); }}><option value="poster">海报</option><option value="banner">Banner</option><option value="standee">立牌</option><option value="special">其他</option></select></Field> : null}{!setup && form.requestType === 'special' ? <TextField label="其他设计类型" value={form.otherDesignType} onChange={(otherDesignType) => onChange({ ...form, otherDesignType })} required /> : null}<Field label="活动开始"><input type="datetime-local" value={form.eventStartAt} onChange={(event) => onChange({ ...form, eventStartAt: event.target.value })} /></Field><Field label="活动结束"><input type="datetime-local" value={form.eventEndAt} onChange={(event) => onChange({ ...form, eventEndAt: event.target.value })} /></Field>{setup ? <TextField label="直播间" value={form.liveRoom} onChange={(liveRoom) => onChange({ ...form, liveRoom })} /> : null}</div></fieldset><fieldset disabled={submitting} className="designer-request-section"><legend>需求资料</legend><div className="designer-request-form-grid"><TextField label="内容" value={form.content} onChange={(content) => onChange({ ...form, content })} /><TextField label="特殊说明" value={form.specialContent} onChange={(specialContent) => onChange({ ...form, specialContent })} /><TextField label="风格 / 主题" value={form.style} onChange={(style) => onChange({ ...form, style })} /><TextField label="颜色" value={form.color} onChange={(color) => onChange({ ...form, color })} /><TextField label="款式 / 规格 / 备注" value={form.specification} onChange={(specification) => onChange({ ...form, specification })} /></div></fieldset>{designerReferenceUploadsEnabled?<fieldset disabled={submitting} className="designer-request-section"><legend>参考资料</legend><ReferenceUpload files={files} items={editing?.request_items ?? []} attachments={editing?.reference_attachments ?? []} note={note} onNote={setNote} onAdd={addFiles} onChangeFile={(file)=>setFiles((current)=>current.map((item)=>item.file===file.file?file:item))} onRemove={(file)=>setFiles((current)=>current.filter((item)=>item!==file))} /></fieldset>:null}</form></SystemModal>; }

function ReferenceUpload({files,items,attachments,note,onNote,onAdd,onChangeFile,onRemove,readonly=false,onDeleteAttachment,removingAttachmentId}:{files:PendingReference[];items:{id:string;item_type:string;item_name:string|null}[];attachments:DesignerReferenceAttachment[];note:string;onNote:(value:string)=>void;onAdd:(files:FileList|File[])=>void;onChangeFile:(file:PendingReference)=>void;onRemove:(file:PendingReference)=>void;readonly?:boolean;onDeleteAttachment?:(file:DesignerReferenceAttachment)=>void;removingAttachmentId?:string}){
  const [dragging,setDragging]=useState(false); const [urls,setUrls]=useState<Record<string,string>>({});
  const open=async(path:string)=>{try{const url=await designerRequestService.getReferenceSignedUrl(path,60);setUrls((current)=>({...current,[path]:url}));window.open(url,'_blank','noopener,noreferrer');}catch(reason){window.alert(`无法读取参考资料：${errorMessage(reason)}`);}};
  return <div className="designer-reference-upload">
    {!readonly?<label className={`designer-reference-dropzone${dragging?' is-dragging':''}`} onDragOver={(event)=>{event.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={(event)=>{event.preventDefault();setDragging(false);onAdd(event.dataTransfer.files);}}><span className="designer-reference-upload-icon"><Upload size={24}/></span><strong>参考图片 / 附件</strong><span>支持 JPG/JPEG/PNG/WebP：10MB；PDF：30MB</span><span className="designer-reference-choose">选择图片 / PDF</span><input className="sr-only" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,.jpg,.jpeg,.png,.webp,.pdf" onChange={(event)=>{onAdd(event.target.files??[]);event.currentTarget.value='';}}/></label>:null}
    <div className="designer-reference-list">{!readonly?files.map((entry)=><div className="designer-reference-row" key={`${entry.file.name}-${entry.file.size}`}><ReferenceFileVisual file={entry.file}/><span><b>{entry.file.name}</b><small>{formatFileSize(entry.file.size)} · 等待上传</small>{items.length?<select value={entry.scope} onChange={(event)=>onChangeFile({...entry,scope:event.target.value as PendingReference['scope'],itemIds:event.target.value==='shared'?[]:entry.itemIds})}><option value="shared">共同参考资料</option><option value="items">指定项目参考资料</option></select>:null}{entry.scope==='items'?<div className="designer-reference-item-options">{items.map((item)=><label key={item.id}><input type="checkbox" checked={entry.itemIds.includes(item.id)} onChange={(event)=>onChangeFile({...entry,itemIds:event.target.checked?[...entry.itemIds,item.id]:entry.itemIds.filter((id)=>id!==item.id)})}/>{item.item_name||item.item_type}</label>)}</div>:null}</span><button type="button" aria-label={`移除 ${entry.file.name}`} onClick={()=>onRemove(entry)}><Trash2 size={16}/></button></div>):null}{attachments.map((file)=>{const image=file.content_type.startsWith('image/');const pdf=file.content_type==='application/pdf';return <div className="designer-reference-row" key={file.id}>{image&&urls[file.storage_path]?<button type="button" className="designer-reference-thumbnail" aria-label={`放大预览 ${file.original_name}`} onClick={()=>void open(file.storage_path)}><img src={urls[file.storage_path]} alt=""/></button>:<FileText size={20}/>}<span><b>{file.original_name}</b><small>{formatFileSize(file.size_bytes)} · {file.reference_scope==='items'?'指定项目参考资料':'共同参考资料'} · 已上传</small></span><button type="button" className={pdf?'designer-reference-pdf-preview':''} aria-label={`预览 ${file.original_name}`} title={pdf?'预览 PDF':'预览图片'} onClick={()=>void open(file.storage_path)}><Eye size={16}/>{pdf?<em>预览 PDF</em>:null}</button><button type="button" aria-label={`下载 ${file.original_name}`} title="下载" onClick={()=>void open(file.storage_path)}><Download size={16}/></button>{onDeleteAttachment?<button type="button" disabled={removingAttachmentId===file.id} aria-label={`移除 ${file.original_name}`} onClick={()=>onDeleteAttachment(file)}><Trash2 size={16}/></button>:null}</div>})}</div>
    {!readonly?<Field label="备注说明"><textarea placeholder="如不同项目参考要求不同，请在此说明，并与美工组确认" value={note} onChange={(event)=>onNote(event.target.value)} /></Field>:null}
  </div>
}
function ReferenceFileVisual({file}:{file:File}){const [url,setUrl]=useState('');useEffect(()=>{if(!file.type.startsWith('image/'))return;const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next);},[file]);return url?<button type="button" className="designer-reference-thumbnail" aria-label={`放大预览 ${file.name}`} onClick={()=>window.open(url,'_blank','noopener,noreferrer')}><img src={url} alt=""/></button>:<FileText size={20}/>}

function IntakeThumbnail({ request }: { request: WorkflowItem }) {
  const image = request.reference_attachments.find((file) => file.reference_scope === 'shared' && file.content_type.startsWith('image/'));
  const [url, setUrl] = useState('');
  const refresh = useCallback(() => { if (!image) { setUrl(''); return; } void designerRequestService.getReferenceSignedUrl(image.storage_path, 60).then(setUrl).catch(() => setUrl('')); }, [image?.id, image?.storage_path]);
  useEffect(() => { refresh(); }, [refresh]);
  return <span className="designer-intake-task-thumb">{url ? <img src={url} alt="" onError={refresh} /> : <FileText size={23} aria-label="任务类型图标" />}</span>;
}

function IntakeMetaCard({ icon, label, value }: { icon: ReactNode; label: string; value: string }) { return <div className="designer-intake-meta-card"><span className="designer-intake-meta-icon" aria-hidden="true">{icon}</span><div><small>{label}</small><b>{value}</b></div></div>; }

/** Production-safe V2 intake presentation using the existing stage list and claim RPC. */
export function DesignerIntakeWorkflowV2() {
  const [items, setItems] = useState<WorkflowItem[]>([]); const [selected, setSelected] = useState<WorkflowItem | null>(null); const [legacyDetail, setLegacyDetail] = useState<WorkflowItem | null>(null); const [sort, setSort] = useState<'oldest' | 'newest'>('oldest'); const [error, setError] = useState(''); const [acknowledged, setAcknowledged] = useState(false); const [mobileDetail, setMobileDetail] = useState(false); const [listScrollY, setListScrollY] = useState(0);
  const load = useCallback(async () => { try { setError(''); setItems(await designerRequestService.listAvailableStages()); } catch (reason) { setError(errorMessage(reason)); } }, []); useEffect(() => { void load(); }, [load]);
  const pending = useMemo(() => items.filter((item) => item.stage?.status === 'unclaimed').sort((a, b) => { const time = new Date(a.created_at).getTime() - new Date(b.created_at).getTime(); const stable = a.id.localeCompare(b.id) || (a.stage?.id ?? '').localeCompare(b.stage?.id ?? ''); return sort === 'oldest' ? time || stable : -time || stable; }), [items, sort]);
  const active = selected && pending.some((item) => item.stage?.id === selected.stage?.id) ? selected : pending[0] ?? null;
  const projectName = active ? itemLabel(active.request_type, active) : '-';
  // A stage has no item id in the existing service contract. Only request-wide references
  // are therefore rendered here; item-scoped references remain on the established detail flow.
  const files = active?.reference_attachments.filter((file) => file.reference_scope === 'shared') ?? [];
  const claimStage = async (stage: DesignerStage) => { try { await designerRequestService.claim(stage.id); setSelected(null); setLegacyDetail(null); setMobileDetail(false); await load(); } catch (reason) { setError(errorMessage(reason)); } };
  const claim = async () => { if (active?.stage) await claimStage(active.stage); };
  const openTask = (task: WorkflowItem) => { if (task.request_items.length > 1) { setLegacyDetail(task); return; } setListScrollY(window.scrollY); setSelected(task); setMobileDetail(true); requestAnimationFrame(() => window.scrollTo({ top: 0 })); }; const returnToList = () => { setMobileDetail(false); requestAnimationFrame(() => window.scrollTo({ top: listScrollY })); };
  useEffect(() => { setAcknowledged(false); }, [active?.stage?.id]);
  return <section className={`designer-request-page designer-intake-page designer-intake-v2${mobileDetail ? ' is-mobile-detail' : ''}`}><header className="designer-request-hero designer-intake-hero"><div><span>DY GROUP · CREATIVE DESK</span><h2>接单中心</h2><p>选择设计 / 制作或活动布置工作区接单。</p></div><button className="designer-request-secondary designer-request-refresh" type="button" onClick={() => void load()}><RefreshCw size={16} />刷新</button></header>{error ? <p className="form-alert">{error}</p> : null}<div className="designer-intake-desk"><aside className="designer-intake-list"><div className="designer-intake-list-head"><h3>待接任务 <em>{pending.length}</em></h3><label>排序<select value={sort} onChange={(event) => setSort(event.target.value as 'oldest' | 'newest')}><option value="oldest">最先申请优先</option><option value="newest">最新申请优先</option></select></label></div><div className="designer-intake-cards">{pending.map((task) => { const name = itemLabel(task.request_type, task); const count = task.reference_attachments.filter((file) => file.reference_scope === 'shared').length + task.reference_urls.length; return <button key={task.stage?.id} type="button" className={`designer-intake-card${active?.stage?.id === task.stage?.id ? ' is-selected' : ''}`} onClick={() => openTask(task)}><IntakeThumbnail request={task} /><span className="designer-intake-card-copy"><b>{name}</b><small>阶段：{stageNames[task.stage?.stage_type ?? ''] || '-'}</small><small>经纪人：{displayEmployee(task.applicant, '-')} · 主播：{task.creator_name || '-'}</small><small>申请日期：{formatMalaysiaDateTime(task.created_at)} · {count} 个附件</small></span><StatusBadge value="待接单" /></button>; })}</div></aside><main className="designer-intake-detail">{active ? <><header className="designer-intake-detail-head"><button className="designer-intake-mobile-back" type="button" onClick={returnToList}>‹ 返回任务列表</button><div className="designer-intake-detail-title"><div><span>当前接单目标 · {stageNames[active.stage?.stage_type ?? ''] || '-'}</span><StatusBadge value="待接单" /></div><h3>{projectName}</h3></div><div className="designer-intake-request-info"><small>申请时间：{formatMalaysiaDateTime(active.created_at)}</small><small>申请编号：{active.id}</small></div></header><section className="designer-intake-meta-grid"><IntakeMetaCard icon={<UserRound size={22} />} label="主播" value={active.creator_name || '-'} /><IntakeMetaCard icon={<AtSign size={22} />} label="平台账号" value={active.platform_account || active.platform_user_id || '-'} /><IntakeMetaCard icon={<UserRound size={22} />} label="经纪人" value={displayEmployee(active.applicant, '-')} /><IntakeMetaCard icon={<MapPin size={22} />} label="区域" value={active.region?.name || '-'} /><IntakeMetaCard icon={<ClipboardList size={22} />} label="任务类型" value={displayTaskType(active.task_type)} /><IntakeMetaCard icon={<Layers3 size={22} />} label="设计项目" value={projectName} /><IntakeMetaCard icon={<CalendarDays size={22} />} label="活动日期" value={active.event_start_at ? formatMalaysiaDateTime(active.event_start_at) : '-'} /><IntakeMetaCard icon={<CalendarDays size={22} />} label="需求完成日期" value={active.event_end_at ? formatMalaysiaDateTime(active.event_end_at) : '-'} /></section><section className="designer-intake-section"><h4>设计要求</h4><dl className="designer-detail-requirements"><DetailField label="尺寸 / 规格" value={active.specification} /><DetailField label="设计内容" value={active.design_content} /><DetailField label="主题 / 风格" value={active.style} /><DetailField label="配色" value={active.color} /><DetailField label="备注" value={active.special_content} /></dl></section><section className="designer-intake-section"><h4>参考资料</h4><ReferenceGallery attachments={files} legacyUrls={active.reference_urls} emptyText="暂无参考资料" showFileMeta preloadImages /></section><footer className="designer-intake-actions"><label><input type="checkbox" checked={acknowledged} onChange={(event) => setAcknowledged(event.target.checked)} />已阅读设计要求与参考资料</label><div><button className="designer-request-secondary" type="button" onClick={returnToList}>暂不接单</button><button className="designer-request-primary" type="button" disabled={!acknowledged} onClick={() => void claim()}>确认接单</button></div></footer></> : <div className="designer-request-empty">暂无待接任务。</div>}</main></div>{legacyDetail ? <RequestDetail request={legacyDetail} stage={legacyDetail.stage} intake onClose={() => setLegacyDetail(null)} onStageAction={(stage, action) => action === 'claim' ? claimStage(stage) : Promise.resolve()} /> : null}</section>;
}

function RequestDetail({ request, stage, intake = false, applicant = false, onClose, onReview, onStageAction }: { request: DesignerRequestV2; stage?: DesignerStage; intake?: boolean; applicant?: boolean; onClose: () => void; onReview?: (stage: DesignerStage, accepted: boolean) => Promise<void>; onStageAction?: (stage: DesignerStage, action: StageAction) => Promise<void> }) {
  const active = stage ?? request.stages.find((item) => item.status === 'awaiting_agent_confirmation') ?? request.stages[0];
  const action = nextAction(active?.status, intake); const setup = request.work_mode === 'setup_only';
  const [removedAttachmentIds,setRemovedAttachmentIds]=useState<string[]>([]); const [cleanupPaths,setCleanupPaths]=useState<Record<string,string>>({}); const [removingAttachmentId,setRemovingAttachmentId]=useState(''); const [referenceError,setReferenceError]=useState('');
  const itemViews = request.request_items.length ? request.request_items : [{ id: 'legacy', item_type: request.request_type, item_name: null, sort_order: 0 }];
  const [selectedItemId, setSelectedItemId] = useState(itemViews[0]?.id ?? 'legacy');
  const [historyOpen, setHistoryOpen] = useState(false);
  const selectedItem = itemViews.find((item) => item.id === selectedItemId) ?? itemViews[0];
  const attachments=request.reference_attachments.filter((file)=>!removedAttachmentIds.includes(file.id));
  const sharedAttachments = attachments.filter((file) => file.reference_scope === 'shared');
  const selectedAttachments = selectedItem?.id === 'legacy' ? [] : attachments.filter((file) => file.reference_scope === 'items' && file.request_item_ids.includes(selectedItem.id));
  const allowRemove=canRemoveDesignerReference(request.status,applicant);
  async function removeAttachment(file:DesignerReferenceAttachment){
    if(!window.confirm(`确定移除“${file.original_name}”吗？此操作会删除参考资料文件。`))return;
    setReferenceError('');setRemovingAttachmentId(file.id);
    try{if(cleanupPaths[file.id])await designerRequestService.retryReferenceStorageCleanup(cleanupPaths[file.id]);else await designerRequestService.deleteReference(file.id);setRemovedAttachmentIds((ids)=>[...ids,file.id]);}
    catch(reason){if(reason instanceof ReferenceStorageCleanupError)setCleanupPaths((paths)=>({...paths,[file.id]:reason.storagePath}));setReferenceError(`移除失败：${errorMessage(reason)}。文件可能仍在安全存储中，请重试移除操作；若持续失败，请联系管理员。`);}
    finally{setRemovingAttachmentId('');}
  }
  const reviewStages = request.stages.filter((item) => item.status === 'awaiting_agent_confirmation');
  const footer = <><button className="designer-request-secondary" type="button" onClick={onClose}>关闭</button>{applicant && onReview ? reviewStages.map((item) => <span className="designer-detail-footer-actions" key={item.id}><button className="designer-request-secondary" type="button" onClick={() => void onReview(item, false)}>反馈问题</button><button className="designer-request-primary" type="button" onClick={() => void onReview(item, true)}>确认完成</button></span>) : null}{!applicant && active && action && onStageAction ? <button className="designer-request-primary" type="button" onClick={() => void onStageAction(active, action)}>{actionLabel(action)}</button> : null}</>;
  return <SystemModal title="美工申请详情" subtitle={`申请编号 · ${request.id}`} className="designer-request-modal designer-detail-modal designer-workspace-modal" onClose={onClose} footer={footer}>
    <section className="designer-workspace-summary"><div className="designer-workspace-identity"><b>{request.creator_name || '-'}</b><span>TikTok ID：{request.platform_user_id || '-'}</span><span>区域：{request.region?.name || '未分配'}</span></div><div className="designer-workspace-summary-rows"><span><small>活动日期与时间</small><DateRangeInline start={request.event_start_at} end={request.event_end_at} />{invalidEventRange(request.event_start_at, request.event_end_at) ? <em>结束时间早于开始时间</em> : null}</span><span><small>申请人</small><b>{displayEmployee(request.applicant, '未分配')}</b></span><span><small>申请日期</small><DateInline value={request.created_at} /></span><span><small>直播间</small><b>{request.live_room || '-'}</b></span></div><div className="designer-workspace-countdown"><small>活动剩余时间</small><strong>{remainingDays(request.event_start_at)}</strong><StatusBadge value={request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ') || '处理中'} /></div></section>
    <section className="designer-workspace-projects"><h4>申请项目 <small>({itemViews.length})</small></h4><div>{itemViews.map((item, index) => <button type="button" key={item.id} className={selectedItem?.id === item.id ? 'is-selected' : ''} onClick={() => setSelectedItemId(item.id)}><i>{index + 1}</i><span><b>{item.item_name || itemLabel(item.item_type, request)}</b><small>{workModeLabel(request.work_mode)} · 负责人：{displayEmployee(request.stages.find((stage) => stage.assignee)?.assignee ?? null, '未分配')}</small></span><StatusBadge value={itemStatusLabel(item, request, setup)} /></button>)}</div></section>
    <div className="designer-workspace-layout"><main className="designer-workspace-main"><header><div><span>项目详情</span><h3>{selectedItem?.item_name || itemLabel(selectedItem?.item_type || request.request_type, request)}</h3></div><StatusBadge value={itemStatusLabel(selectedItem, request, setup)} /></header><div className="designer-workspace-progress">{request.stages.length ? request.stages.map((item) => <article key={item.id} className={`stage-${item.stage_type} is-${item.status}`}><i /><b>{stageNames[item.stage_type]}</b><small>{displayStageStatus(item)}</small></article>) : <div className="designer-detail-empty">暂无阶段记录</div>}</div><div className="designer-workspace-content-grid"><section className="designer-workspace-requirements"><h4>设计要求</h4><dl className="designer-detail-requirements"><DetailField label="项目类型" value={setup ? '活动布置' : itemLabel(selectedItem?.item_type || request.request_type, request)} /><DetailField label="工作方式" value={workModeLabel(request.work_mode)} /><DetailField label="尺寸 / 规格" value={request.specification} /><DetailField label="内容" value={request.design_content} /><DetailField label="主题 / 风格" value={request.style} /><DetailField label="颜色" value={request.color} /><DetailField label="备注" value={request.special_content} /></dl>{request.reference_note ? <section className="designer-detail-note"><b>共同备注</b><p>{request.reference_note}</p></section> : null}</section><section className="designer-workspace-references"><h4>参考资料</h4>{designerReferenceUploadsEnabled ? <ReferenceGallery attachments={[...sharedAttachments, ...selectedAttachments]} legacyUrls={request.reference_urls} onDelete={allowRemove ? removeAttachment : undefined} removingAttachmentId={removingAttachmentId} preloadImages={applicant} /> : <div className="designer-detail-empty">暂无参考资料</div>}{referenceError ? <p className="designer-request-read-error">{referenceError}</p> : null}</section></div><section className="designer-workspace-results"><h4>{setup ? '现场完成照片' : '设计成果'}</h4><ReferenceGallery attachments={[]} legacyUrls={request.design_urls} emptyText={setup ? '暂无现场完成照片' : '暂无设计成果'} /></section><section className="designer-workspace-history"><button type="button" aria-expanded={historyOpen} onClick={() => setHistoryOpen((open) => !open)}><span>处理记录</span><span>{historyOpen ? '收起' : '展开'}⌄</span></button>{historyOpen ? <div className="designer-detail-timeline"><TimelineEntry title="申请提交" time={request.created_at} />{request.stages.flatMap((item) => [item.accepted_at ? <TimelineEntry key={`${item.id}-accepted`} title={`${stageNames[item.stage_type]}接单`} time={item.accepted_at} tone="pending" /> : null, item.submitted_at ? <TimelineEntry key={`${item.id}-submitted`} title={`${stageNames[item.stage_type]}提交`} time={item.submitted_at} tone="active" /> : null, item.confirmed_at ? <TimelineEntry key={`${item.id}-confirmed`} title={`${stageNames[item.stage_type]}确认 / 完成`} time={item.confirmed_at} tone="completed" /> : null, item.feedback ? <TimelineEntry key={`${item.id}-feedback`} title="退回修改" detail={item.feedback} tone="revision" /> : null])}</div> : null}</section></main><aside className="designer-workspace-sidebar"><section><h4>当前状态</h4><StatusBadge value={itemStatusLabel(selectedItem, request, setup)} /><dl><dt>当前阶段</dt><dd>{active ? stageNames[active.stage_type] : '-'}</dd><dt>负责人</dt><dd>{displayEmployee(request.stages.find((stage) => stage.assignee)?.assignee ?? null, '未分配')}</dd></dl></section>{itemViews.length > 1 ? <section><h4>相关项目</h4>{itemViews.map((item) => <button type="button" key={item.id} className={selectedItem?.id === item.id ? 'is-selected' : ''} onClick={() => setSelectedItemId(item.id)}>{item.item_name || itemLabel(item.item_type, request)}<span>›</span></button>)}</section> : null}</aside></div>
  </SystemModal>;
}

function DetailField({ label, value }: { label: string; value: string | null | undefined }) { return value ? <><dt>{label}</dt><dd>{value}</dd></> : null; }
function DateInline({ value }: { value: string | null }) { return <b className="designer-workspace-date-inline">{formatMalaysiaDateTime(value)}</b>; }
function DateRangeInline({ start, end }: { start: string | null; end: string | null }) { return <b className="designer-workspace-date-inline">{formatMalaysiaRange(start, end)}</b>; }
function TimelineEntry({ title, time, detail, tone = 'submitted' }: { title: string; time?: string | null; detail?: string; tone?: 'submitted'|'pending'|'active'|'completed'|'revision' }) { return <article className={`is-${tone}`}><i /><div><b>{title}</b>{time ? <small>{formatMalaysiaDateTime(time)}</small> : null}{detail ? <p>{detail}</p> : null}</div></article>; }
function itemLabel(type: string, request: DesignerRequestV2) { if (type === 'setup') return '活动布置'; if (type === 'special') return request.other_design_type || '其他设计'; return designTypeNames[type as DesignType] || type || displayDesignType(request); }
function itemStatusLabel(_item: { item_type: string } | undefined, request: DesignerRequestV2, setup: boolean) { const matching = request.stages.find((stage) => setup ? stage.stage_type === 'setup' : stage.stage_type === 'design') ?? request.stages[0]; return matching ? displayStageStatus(matching) : request.status === 'cancelled' ? '已取消' : '待处理'; }
function remainingDays(value: string | null) { if (!value) return '-'; const diff = Math.ceil((new Date(value).getTime() - Date.now()) / 86400000); return diff < 0 ? `已过期 ${Math.abs(diff)} 天` : diff === 0 ? '今天' : `剩余 ${diff} 天`; }
function invalidEventRange(start: string | null, end: string | null) { return Boolean(start && end && new Date(end).getTime() < new Date(start).getTime()); }
function formatMalaysiaDateTime(value: string | null | undefined) { return value ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Kuala_Lumpur', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)).replace(/\//g, '-') : '-'; }
function formatMalaysiaRange(start: string | null, end: string | null) { return start || end ? `${formatMalaysiaDateTime(start)}${end ? ` → ${formatMalaysiaDateTime(end)}` : ''}` : '-'; }

export function ReferenceGallery({ attachments, legacyUrls, emptyText = '暂无附件', onDelete, removingAttachmentId, showFileMeta = false, preloadImages = false }: { attachments: DesignerReferenceAttachment[]; legacyUrls: string[]; emptyText?: string; onDelete?: (file: DesignerReferenceAttachment) => void; removingAttachmentId?: string; showFileMeta?: boolean; preloadImages?: boolean }) {
  const [urls, setUrls] = useState<Record<string, { value: string; expiresAt: number }>>({}); const urlsRef = useRef<Record<string, { value: string; expiresAt: number }>>({}); const attachmentsRef = useRef(attachments); attachmentsRef.current = attachments; const refreshedImageIds = useRef(new Set<string>()); const [preview, setPreview] = useState<{ url: string; contentType: string } | null>(null);
  const imageAttachmentKey = attachments.filter((file) => file.content_type.startsWith('image/')).map((file) => `${file.id}:${file.storage_path}`).join('|');
  const resolve = useCallback(async (file: DesignerReferenceAttachment, forceRefresh = false) => { const existing = urlsRef.current[file.id]; if (!forceRefresh && existing && existing.expiresAt > Date.now()) return existing.value; const value = await designerRequestService.getReferenceSignedUrl(file.storage_path, 60); const next = { value, expiresAt: Date.now() + 55000 }; urlsRef.current = { ...urlsRef.current, [file.id]: next }; setUrls((current) => ({ ...current, [file.id]: next })); return value; }, []);
  useEffect(() => { if (!preloadImages) return; void Promise.all(attachmentsRef.current.filter((file) => file.content_type.startsWith('image/')).map(async (file) => { try { await resolve(file); } catch { /* Preserve the safe click-to-preview fallback. */ } })); }, [imageAttachmentKey, preloadImages, resolve]);
  const refreshFailedImage = (file: DesignerReferenceAttachment) => { if (refreshedImageIds.current.has(file.id)) return; refreshedImageIds.current.add(file.id); void resolve(file, true); };
  const open = async (file: DesignerReferenceAttachment) => { try { setPreview({ url: await resolve(file), contentType: file.content_type }); } catch (reason) { window.alert(`无法读取参考资料：${errorMessage(reason)}`); } };
  const download = async (file: DesignerReferenceAttachment) => { try { const url = await designerRequestService.getReferenceDownloadSignedUrl(file.storage_path, file.original_name); const anchor = document.createElement('a'); anchor.href = url; anchor.download = file.original_name; document.body.appendChild(anchor); anchor.click(); anchor.remove(); } catch (reason) { window.alert(`下载参考资料失败：${errorMessage(reason)}`); } };
  useEffect(() => {
    if (!preview) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.stopPropagation();
      setPreview(null);
    };
    document.addEventListener('keydown', closeOnEscape, true);
    return () => document.removeEventListener('keydown', closeOnEscape, true);
  }, [preview]);
  if (!attachments.length && !legacyUrls.length) return <div className="designer-detail-empty">{emptyText}</div>;
  return <><div className="designer-detail-gallery">{attachments.map((file) => <article key={file.id} className="designer-detail-file">{file.content_type.startsWith('image/') ? <button type="button" className="designer-detail-image" onClick={() => void open(file)}>{urls[file.id] ? <img src={urls[file.id].value} alt={file.original_name} onError={preloadImages ? () => refreshFailedImage(file) : undefined} /> : <span>查看图片</span>}</button> : <button type="button" className="designer-detail-pdf" onClick={() => void open(file)}><FileText size={24} /><span>PDF</span></button>}<b title={file.original_name}>{file.original_name}</b><small>{showFileMeta ? `${file.content_type.split('/').pop()?.toUpperCase() || '文件'} · ${formatFileSize(file.size_bytes)}` : file.reference_scope === 'items' ? '项目专属资料' : '共同参考资料'}</small>{showFileMeta ? <small className="designer-intake-file-scope">{file.reference_scope === 'items' ? '项目专属资料' : '共同参考资料'}</small> : null}<div><button type="button" onClick={() => void open(file)}>{file.content_type === 'application/pdf' ? '预览 PDF' : '查看大图'}</button><button type="button" onClick={() => void download(file)}>{file.content_type === 'application/pdf' ? '下载 PDF' : '下载原图'}</button>{onDelete ? <button type="button" disabled={removingAttachmentId === file.id} onClick={() => onDelete(file)}>移除</button> : null}</div></article>)}{legacyUrls.map((url, index) => <article key={url} className="designer-detail-file"><button type="button" className="designer-detail-image" onClick={() => setPreview({ url, contentType: 'image/*' })}><img src={url} alt={`成果 ${index + 1}`} /></button><b>成果图片 {index + 1}</b><small>现有成果资料</small><div><button type="button" onClick={() => setPreview({ url, contentType: 'image/*' })}>查看大图</button><a href={url} download>下载原图</a></div></article>)}</div>{preview ? createPortal(<div className="designer-detail-preview" role="presentation" onMouseDown={() => setPreview(null)}><section role="dialog" aria-modal="true" aria-label={preview.contentType === 'application/pdf' ? 'PDF 预览' : '图片预览'} onMouseDown={(event) => event.stopPropagation()}><button type="button" aria-label="关闭预览" onClick={() => setPreview(null)}><X size={20} /></button>{preview.contentType === 'application/pdf' ? <iframe title="PDF 预览" src={preview.url} /> : <img src={preview.url} alt="附件预览" />}</section></div>, document.body) : null}</>;
}

function CancelModal({ onClose, onConfirm }: { onClose: () => void; onConfirm: () => Promise<void> }) { return <SystemModal title="取消申请" wide={false} className="designer-request-modal designer-request-confirm-modal" onClose={onClose} footer={<><button className="designer-request-secondary" type="button" onClick={onClose}>返回</button><button className="designer-request-danger" type="button" onClick={() => void onConfirm()}>确认取消</button></>}><p>确定取消这份美工申请吗？</p><p>取消后将保留记录，但不能继续接单或处理。</p></SystemModal>; }

function nextAction(status: StageStatus | undefined, intake: boolean): StageAction | null { if (intake) return 'claim'; if (status === 'scheduled') return 'arrange'; if (status === 'arranged') return 'start'; return status === 'in_progress' || status === 'revision' ? 'submit' : null; }
function actionLabel(action: StageAction | null) { return action === 'claim' ? '接单' : action === 'arrange' ? '确认安排' : action === 'start' ? '开始布置' : action === 'submit' ? '提交完成确认' : '暂无可执行操作'; }
function StatusBadge({ value }: { value: string }) { const kind = value === '已取消' ? 'cancelled' : value.includes('完成') ? 'done' : value.includes('进行') ? 'active' : 'pending'; return <span className={`designer-request-badge designer-request-badge-${kind}`}>{value}</span>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="designer-request-field"><span>{label}</span>{children}</label>; }
function TextField({ label, value, onChange, required = false }: { label: string; value: string; onChange: (value: string) => void; required?: boolean }) { return <Field label={label}><input required={required} value={value} onChange={(event) => onChange(event.target.value)} /></Field>; }
function displayTaskType(taskType: TaskType | null): string { return taskType ? taskTypeNames[taskType] : '-'; }
function displayDesignType(request: DesignerRequestV2): string { if (request.work_mode === 'setup_only') return '-'; return request.request_type === 'special' ? request.other_design_type || '-' : designTypeNames[request.request_type]; }
function workModeLabel(workMode: WorkMode | null): string { return workMode === 'design_production' ? '设计 + 制作' : workMode === 'setup_only' ? '布置' : '纯设计'; }
function dateInput(value: string | null): string { return value ? value.slice(0, 16) : ''; }
function formatDate(value: string | null): string { return value ? value.replace('T', ' ').slice(0, 16) : '-'; }
function displayEmployee(employee: { full_name: string | null; nickname: string | null } | null, fallback: string) { return employee?.nickname || employee?.full_name || fallback; }
const malaysiaDateFormatter = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kuala_Lumpur', year: 'numeric', month: '2-digit', day: '2-digit' });
function malaysiaDateKey(value: string | null) { if (!value) return ''; const parts = malaysiaDateFormatter.formatToParts(new Date(value)); const fields = Object.fromEntries(parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value])); return `${fields.year}-${fields.month}-${fields.day}`; }
function malaysiaTodayKey() { return malaysiaDateKey(new Date().toISOString()); }
function calendarDayNumber(dateKey: string) { const [year, month, day] = dateKey.split('-').map(Number); return Math.floor(Date.UTC(year, month - 1, day) / 86400000); }
function matchesKeyword(request: DesignerRequestV2, keyword: string) { const query = keyword.trim().toLowerCase(); return !query || [request.creator_name, request.platform_user_id, request.platform_account].some((value) => value?.toLowerCase().includes(query)); }
function agentBucket(request: DesignerRequestV2): Exclude<AgentStatusFilter, 'all'> { if (request.status === 'completed') return 'completed'; if (request.status === 'cancelled') return 'cancelled'; if (request.stages.some((stage) => stage.status === 'awaiting_agent_confirmation')) return 'awaiting'; return 'processing'; }
function sortAgentRequests(first: DesignerRequestV2, second: DesignerRequestV2) { const rank: Record<Exclude<AgentStatusFilter, 'all'>, number> = { awaiting: 0, processing: 1, completed: 2, cancelled: 3 }; return rank[agentBucket(first)] - rank[agentBucket(second)] || new Date(second.created_at).getTime() - new Date(first.created_at).getTime(); }
function matchesIntake(request: WorkflowItem, filters: IntakeFilters, workstream: DesignerWorkstream) { return matchesKeyword(request, filters.keyword) && (!filters.taskType || request.task_type === filters.taskType) && (workstream === 'setup' || !filters.designType || request.request_type === filters.designType) && (!filters.applicant || displayEmployee(request.applicant, '') === filters.applicant) && (!filters.eventDate || malaysiaDateKey(request.event_start_at) === filters.eventDate) && (!filters.submittedDate || malaysiaDateKey(request.created_at) === filters.submittedDate) && (!filters.region || request.region?.name === filters.region); }
function matchesProgress(request: WorkflowItem, filters: ProgressFilters) { const stage = request.stage; if (!stage) return false; return (!filters.activeOnly || stage.status === 'in_progress' || stage.status === 'revision') && (!filters.owner || displayEmployee(stage.assignee, '').toLowerCase().includes(filters.owner.trim().toLowerCase())) && (!filters.stageType || stage.stage_type === filters.stageType) && (!filters.status || stage.status === filters.status) && matchesKeyword(request, filters.keyword) && (!filters.applicant || displayEmployee(request.applicant, '') === filters.applicant) && (!filters.eventDate || malaysiaDateKey(request.event_start_at) === filters.eventDate); }
function compareEventDate(first: DesignerRequestV2, second: DesignerRequestV2) { const firstDate = first.event_start_at ? calendarDayNumber(malaysiaDateKey(first.event_start_at)) : Number.MAX_SAFE_INTEGER; const secondDate = second.event_start_at ? calendarDayNumber(malaysiaDateKey(second.event_start_at)) : Number.MAX_SAFE_INTEGER; return firstDate - secondDate; }
function sortIntakeRequests(first: WorkflowItem, second: WorkflowItem, workstream: DesignerWorkstream) { return workstream === 'setup' ? compareEventDate(first, second) || new Date(first.created_at).getTime() - new Date(second.created_at).getTime() : new Date(first.created_at).getTime() - new Date(second.created_at).getTime(); }
function sortProgressRequests(first: WorkflowItem, second: WorkflowItem) { const rank = (item: WorkflowItem) => item.stage?.status === 'in_progress' || item.stage?.status === 'revision' ? 0 : item.stage?.status === 'scheduled' || item.stage?.status === 'arranged' ? 1 : 2; return rank(first) - rank(second) || compareEventDate(first, second) || new Date(second.stage?.accepted_at ?? 0).getTime() - new Date(first.stage?.accepted_at ?? 0).getTime(); }
function requestRisk(request: WorkflowItem) { if (!request.event_start_at || request.status === 'completed' || request.status === 'cancelled' || request.stage?.status === 'completed') return ''; const days = calendarDayNumber(malaysiaDateKey(request.event_start_at)) - calendarDayNumber(malaysiaTodayKey()); if (days < 0) return '已过活动日期'; if (request.work_mode === 'setup_only' && days < 10) return '时间较紧'; if (request.work_mode === 'design_production' && days < 15) return '制作周期紧张'; return ''; }
function formatFileSize(size:number){return size>=1024*1024?`${(size/(1024*1024)).toFixed(1)} MB`:`${Math.max(1,Math.round(size/1024))} KB`;}
type DesignerRequestRpcError = { code?: unknown; message?: unknown; details?: unknown; hint?: unknown };

function errorMessage(reason: unknown): string {
  if (reason instanceof Error) return reason.message;

  if (reason && typeof reason === 'object') {
    const error = reason as DesignerRequestRpcError;
    const message = typeof error.message === 'string' && error.message.trim() ? error.message : '';

    if (import.meta.env.DEV) {
      console.error('Designer request operation failed', {
        code: typeof error.code === 'string' ? error.code : undefined,
        message: message || undefined,
        details: typeof error.details === 'string' ? error.details : undefined,
        hint: typeof error.hint === 'string' ? error.hint : undefined,
      });
    }

    if (message) return message;
  }

  return typeof reason === 'string' && reason.trim() ? reason : '操作失败';
}
